#!/usr/bin/env bash
# Writes contract.cue from contract.json, the shop's hand-written contract, for cue vet against the
# meta-schema and for the docuconf CLI. CI runs it and fails when contract.cue changes. Needs cue.
set -euo pipefail
cd "$(dirname "$0")"
cue="${CUE:-cue}"
{
  cat <<'HEADER'
// Code generated by gen-contract-cue.sh from contract.json. DO NOT EDIT.
package shop

import "docuconf.dev/contract"

contract.#Contract & {
HEADER
  "$cue" export contract.json --out cue | sed 's/^/\t/'
  echo '}'
} >contract.cue
"$cue" fmt contract.cue
